# frozen_string_literal: true

require "yaml"
require "fileutils"
require_relative "config_loader"
require_relative "project_detector"

# One-time interactive generator for fastlane/config/environments.yml.
module ProjectBootstrap
  DEFAULT_ENVIRONMENTS = %w[development staging uat production].freeze
  ENV_EXAMPLE_PATH = File.join(DistributionConfig.root, ".env.example").freeze

  HEADER = <<~YAML
    # =============================================================================
    # Mobile Distribution Framework Configuration (generated by `fastlane init_project`)
    # =============================================================================
    # Project-specific settings. Never store secrets here: use .env / CI secrets.
    # gradle_task is the source of truth for Android builds.
    # Per-run choices (flavor, APK/AAB, testers...) can be picked with `fastlane setup`.
    # =============================================================================
  YAML

  class << self
    def run
      ui.header("Project setup")
      path = DistributionConfig.config_path

      if File.exist?(path)
        return nil unless ui.confirm("#{File.basename(path)} already exists. Replace it (a .bak copy is kept)?")

        FileUtils.cp(path, "#{path}.bak")
        ui.message("Backup: #{path}.bak")
      end

      config = build_config
      FileUtils.mkdir_p(File.dirname(path))
      File.write(path, HEADER + "\n" + config.to_yaml.sub(/\A---\n/, ""))
      ui.success("Wrote #{path}")

      added = append_env_example(config)
      ui.message("Added #{added.size} key(s) to .env.example: #{added.join(', ')}") unless added.empty?
      ui.message("Next: fill .env, then run `fastlane android doctor` / `fastlane setup`.")
      path
    end

    private

    def build_config
      name = ask("App name", DistributionConfig.detected_app_name)
      identifier = ask("App identifier / package", DistributionConfig.detected_package_name.to_s)
      organization = ask("Organization", "Default")

      environments = ask_environments
      default_env = ui.select("Default environment:", environments)

      android_on = ui.confirm("Enable Android?") if ProjectDetector.android_present? || ui.confirm("No android/ project detected. Configure Android anyway?")
      ios_on = ui.confirm("Enable iOS?") if ProjectDetector.ios_present? || ui.confirm("No ios/ project detected. Configure iOS anyway?")

      config = {
        "project" => {
          "name" => name,
          "identifier" => identifier,
          "organization" => organization,
          "default_environment" => default_env
        },
        "android" => android_on ? android_section(environments) : { "enabled" => false },
        "ios" => ios_on ? ios_section(name, identifier, environments) : { "enabled" => false },
        "notifications" => notifications_section,
        "release_notes" => {
          "enabled" => true,
          "source" => "git",
          "commit_count" => 10,
          "prefix" => "Automated Mobile Distribution"
        },
        "security" => { "production_requires_ci" => false },
        "artifact" => {
          "naming" => {
            "enabled" => true,
            "pattern" => "{project}-{environment}-v{version}-{build}.{extension}"
          }
        }
      }
      config
    end

    def ask_environments
      ui.message("Default environments: #{DEFAULT_ENVIRONMENTS.join(', ')}")
      raw = ask("Environments (comma separated)", DEFAULT_ENVIRONMENTS.join(","))
      names = raw.split(",").map { |item| item.strip.downcase.gsub(/[^a-z0-9_-]+/, "_") }.reject(&:empty?).uniq
      names.empty? ? DEFAULT_ENVIRONMENTS.dup : names
    end

    def android_section(environments)
      project_dir = ask("Android project dir", "android")
      flavors = ProjectDetector.android_flavors(project_dir)
      build_types = ProjectDetector.android_build_types(project_dir)
      ui.message(flavors.empty? ? "No product flavors detected." : "Detected flavors: #{flavors.join(', ')}")

      envs = environments.each_with_object({}) do |env, result|
        ui.header("Android · #{env}")
        flavor = flavors.empty? ? "" : pick_flavor(flavors, env)
        build_type = ui.select("Build type for #{env}:", ordered(build_types, "release"))
        artifact = ui.select("Default artifact for #{env}:", %w[APK AAB])
        firebase = ui.confirm("Distribute #{env} via Firebase App Distribution?")
        key = env_key(env)

        entry = { "description" => "#{env.capitalize} Android distribution" }
        entry["flavor"] = flavor unless flavor.empty?
        entry["build_type"] = build_type
        entry["gradle_task"] = ProjectDetector.gradle_task(flavor: flavor, build_type: build_type, artifact: artifact)
        entry["artifact"] = {
          "type" => artifact,
          "glob" => ProjectDetector.artifact_glob(flavor: flavor, build_type: build_type, artifact: artifact, project_dir: project_dir)
        }
        entry["firebase"] = {
          "enabled" => firebase,
          "app_id" => "${FIREBASE_ANDROID_#{key}_APP_ID}",
          "groups" => "${FIREBASE_ANDROID_#{key}_GROUPS}",
          "testers" => ""
        }
        entry["app_testing"] = { "enabled" => firebase && artifact == "APK" && !production?(env) }
        entry["release_notes"] = { "enabled" => true, "source" => "git", "commit_count" => production?(env) ? 20 : 10 }
        entry["safety"] = production_safety if production?(env)
        result[env] = entry
      end

      {
        "enabled" => true,
        "project_dir" => project_dir,
        "use_flavors" => !flavors.empty?,
        "build" => { "clean_before_build" => false, "gradle_options" => "" },
        "environments" => envs
      }
    end

    def ios_section(name, identifier, environments)
      project_dir = ask("iOS project dir", "ios")
      schemes = ProjectDetector.ios_schemes(project_dir)
      workspace = ask("Workspace", DistributionConfig.detected_ios_workspace)
      signing = ui.select("Code signing:", %w[automatic match])

      envs = environments.each_with_object({}) do |env, result|
        ui.header("iOS · #{env}")
        scheme = schemes.empty? ? ask("Scheme for #{env}", name) : ui.select("Scheme for #{env}:", ordered(schemes, name))
        entry = {
          "description" => "#{env.capitalize} iOS/TestFlight distribution",
          "workspace" => workspace,
          "scheme" => scheme,
          "bundle_identifier" => ask("Bundle identifier for #{env}", identifier),
          "export_method" => "app-store",
          "versioning" => { "auto_increment_build_number" => true },
          "testflight" => {
            "enabled" => ui.confirm("Upload #{env} to TestFlight?"),
            "groups" => [],
            "notify_external_testers" => true,
            "skip_waiting_for_build_processing" => true
          },
          "release_notes" => { "enabled" => true, "source" => "git", "commit_count" => production?(env) ? 20 : 10 }
        }
        # `fastlane ios firebase`: Ad Hoc IPA to Firebase App Distribution (no App Store Connect key needed).
        key = env_key(env)
        entry["firebase"] = {
          "enabled" => !production?(env) && ui.confirm("Distribute #{env} via Firebase App Distribution (Ad Hoc)?"),
          "export_method" => "ad-hoc",
          "app_id" => "${FIREBASE_IOS_#{key}_APP_ID}",
          "groups" => "${FIREBASE_IOS_#{key}_GROUPS}",
          "testers" => ""
        }
        entry["safety"] = production_safety if production?(env)
        result[env] = entry
      end

      {
        "enabled" => true,
        "project_dir" => project_dir,
        "build" => { "install_pods" => true },
        "signing" => {
          "method" => signing,
          "team_id" => "${APPLE_TEAM_ID}",
          "type" => "appstore",
          "readonly_in_ci" => true,
          "update_project_signing" => false
        },
        "environments" => envs
      }
    end

    def notifications_section
      teams = ui.confirm("Send Microsoft Teams notifications?")
      slack = ui.confirm("Send Slack notifications?")
      {
        "teams" => { "enabled" => teams, "webhook_url" => "${TEAMS_WEBHOOK_URL}" },
        "slack" => { "enabled" => slack, "webhook_url" => "${SLACK_WEBHOOK_URL}" }
      }
    end

    def pick_flavor(flavors, env)
      guess = flavors.find { |f| f.casecmp?(env) } ||
              flavors.find { |f| env.start_with?(f.downcase) || f.downcase.start_with?(env[0, 3]) }
      picked = ui.select("Flavor for #{env}:", ordered(["(none)"] + flavors, guess))
      picked == "(none)" ? "" : picked
    end

    def production_safety
      { "require_confirmation" => true, "require_ci" => false, "allowed_branches" => ["main"] }
    end

    def production?(env)
      %w[production prod release].include?(env)
    end

    def env_key(env)
      key = env.upcase.gsub(/[^A-Z0-9]+/, "_")
      # Match the framework convention used in .env.example: DEV, STAGING, UAT, PROD.
      { "DEVELOPMENT" => "DEV", "PRODUCTION" => "PROD" }.fetch(key, key)
    end

    # Appends missing ${VAR} placeholders from the generated config to .env.example.
    def append_env_example(config)
      vars = config.to_yaml.scan(/\$\{([A-Z][A-Z0-9_]*)\}/).flatten.uniq
      ios_firebase = config.dig("ios", "environments").to_h.values.any? { |env| env.dig("firebase", "enabled") }
      vars += %w[FIREBASE_SERVICE_CREDENTIALS_FILE] if config.dig("android", "enabled") || ios_firebase
      vars += %w[APP_STORE_CONNECT_KEY_ID APP_STORE_CONNECT_ISSUER_ID APP_STORE_CONNECT_KEY_FILE] if config.dig("ios", "enabled")

      existing = File.exist?(ENV_EXAMPLE_PATH) ? File.read(ENV_EXAMPLE_PATH) : ""
      missing = vars.reject { |var| existing.match?(/^#{Regexp.escape(var)}=/) }
      return [] if missing.empty?

      File.open(ENV_EXAMPLE_PATH, "a") do |file|
        file.write("\n") unless existing.empty? || existing.end_with?("\n")
        file.write("\n# Added by `fastlane init_project`\n")
        missing.each { |var| file.write("#{var}=\n") }
      end
      missing
    end

    def ordered(options, current)
      match = options.find { |option| option.to_s.casecmp?(current.to_s) }
      match ? [match] + (options - [match]) : options
    end

    def ask(message, default = "")
      suffix = default.to_s.empty? ? "" : " [#{default}]"
      value = ui.input("#{message}#{suffix}:").to_s.strip
      value.empty? ? default.to_s : value
    end

    def ui
      FastlaneCore::UI
    end
  end
end
